CREATE TABLE IF NOT EXISTS sponsor_prospects (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  slug TEXT NOT NULL UNIQUE,
  organization TEXT NOT NULL,
  partner_type TEXT NOT NULL CHECK (partner_type IN ('local_business','corporate_sponsor','media_production','network_development','distribution','industry_association','funding','service_provider')),
  division TEXT NOT NULL DEFAULT 'cross_division' CHECK (division IN ('business_network','summits_events','marketplace','academy','land_experiences','media','cross_division')),
  category TEXT NOT NULL DEFAULT '',
  location TEXT NOT NULL DEFAULT '',
  website TEXT NOT NULL DEFAULT '',
  source_url TEXT NOT NULL DEFAULT '',
  contact_route TEXT NOT NULL DEFAULT '',
  public_phone TEXT NOT NULL DEFAULT '',
  public_email TEXT NOT NULL DEFAULT '',
  contact_name TEXT NOT NULL DEFAULT '',
  fit_score INTEGER NOT NULL DEFAULT 0 CHECK (fit_score BETWEEN 0 AND 10),
  stage TEXT NOT NULL DEFAULT 'research' CHECK (stage IN ('research','qualified','contact_route_verified','owner_approved','contacted','responded','discovery','proposal','negotiating','contracted','nurture','closed_won','closed_lost')),
  estimated_value_cents INTEGER CHECK (estimated_value_cents IS NULL OR estimated_value_cents BETWEEN 0 AND 100000000),
  next_follow_up_date TEXT,
  last_contacted_at TEXT,
  owner_approved_at TEXT,
  owner_approved_by TEXT NOT NULL DEFAULT '',
  qualification_notes TEXT NOT NULL DEFAULT '',
  notes TEXT NOT NULL DEFAULT '',
  source_checked_at TEXT NOT NULL DEFAULT '2026-11-17',
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  updated_at TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE INDEX IF NOT EXISTS idx_sponsor_prospects_stage ON sponsor_prospects(stage, fit_score DESC);
CREATE INDEX IF NOT EXISTS idx_sponsor_prospects_type ON sponsor_prospects(partner_type, division);
CREATE INDEX IF NOT EXISTS idx_sponsor_prospects_followup ON sponsor_prospects(next_follow_up_date);

CREATE TABLE IF NOT EXISTS sponsor_prospect_activities (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  prospect_id INTEGER NOT NULL,
  activity_type TEXT NOT NULL CHECK (activity_type IN ('research','qualification','approval','outreach','response','meeting','proposal','contract','note')),
  summary TEXT NOT NULL,
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  FOREIGN KEY (prospect_id) REFERENCES sponsor_prospects(id) ON DELETE CASCADE
);
CREATE INDEX IF NOT EXISTS idx_sponsor_prospect_activities_prospect ON sponsor_prospect_activities(prospect_id, created_at DESC);

